function fast_cascade(preferred, alternatives) {
    // Ensure we have exactly 3 providers to try in parallel
    let pool = [];
    pool[0] = preferred;
    let count = 1;
    for (let i = 0; i < len(alternatives) and count < 3; i++) {
        if (alternatives[i] != preferred) {
            pool[count] = alternatives[i];
            count = count + 1;
        }
    }
    // If less than 3, fill with available providers
    while count < 3 and count < len(alternatives) {
        pool[count] = alternatives[count];
        count = count + 1;
    }

    // Shared result container
    let result = {};
    dict_set(result, "response", null);
    dict_set(result, "done", false);

    // Launch 3 parallel attempts
    for (let tid = 0; tid < 3; tid++) {
        thread spawn (pool[tid], result) {
            if dict_get(result, "done") { return; }
            let provider = pool[tid];
            let url = "https://" + provider + "/route";
            let headers = { "X-Route-Attempt": "parallel" };

            try3 {
                let resp = http_post_headers(url, headers, "", 3000);
                if resp.status == 200 {
                    lock {
                        if not dict_get(result, "done") {
                            dict_set(result, "response", resp.body);
                            dict_set(result, "done", true);
                        }
                    }
                }
            } fail {
                // Ignore failure, another thread may succeed
            }
        }
    }

    // Wait up to 4 seconds for first success
    let wait = 0;
    while wait < 4000 {
        if dict_get(result, "done") {
            return dict_get(result, "response");
        }
        sleep(10);
        wait = wait + 10;
    }

    return null; // Timeout
}
